];
const prefixes = ["aws-0", "aws-1"];

const targets = [];
for (const p of prefixes) for (const r of regions) targets.push(`${p}-${r}.pooler.supabase.com`);

async function probe(host) {
  const client = new pg.Client({
    host,
    port: 5432,
    user: `postgres.${ref}`,
    password: "definitely-not-the-password",
    database: "postgres",
    ssl: { rejectUnauthorized: false },
    connectionTimeoutMillis: 8000,
    query_timeout: 8000,
  });
  try {
    await client.connect();
    return { host, verdict: "CONNECTED (unexpected)" };
  } catch (err) {
    const msg = String(err.message || err.code || "");
    let verdict = "unknown";
    if (/tenant or user not found/i.test(msg)) verdict = "no-tenant-here";
    else if (/password authentication failed/i.test(msg)) verdict = "TENANT MATCHES (bad password, as expected)";
    else if (/ENOTFOUND|EAI_AGAIN/i.test(msg)) verdict = "dns-fail";
    else verdict = msg.slice(0, 120);
    return { host, verdict };
  } finally {
    await client.end().catch(() => {});
  }
}

const results = [];
const batchSize = 8;
for (let i = 0; i < targets.length; i += batchSize) {
  const batch = targets.slice(i, i + batchSize);
  results.push(...(await Promise.all(batch.map(probe))));
}

const hits = results.filter((r) => r.verdict.startsWith("TENANT MATCHES"));
const interesting = results.filter((r) => !r.verdict.startsWith("no-tenant-here") && !r.verdict.startsWith("dns-fail"));
