import { globSync } from "fs";

const root = process.cwd();

// 1. Strip the inline tailwind.config <script> blocks from each page
for (const file of fs.readdirSync(root).filter(f => f.endsWith(".html"))) {
  const p = `${root}/${file}`;
  const src = fs.readFileSync(p, "utf8");
  // the block is: optional comment, <script>, tailwind.config = {...};, </script>
  const re = /[ \t]*<!-- Tailwind CDN -->\n[ \t]*<script>\n[ \t]*tailwind\.config = \{[\s\S]*?\n[ \t]*\};\n[ \t]*<\/script>\n?|[ \t]*<script>\n[ \t]*tailwind\.config = \{[\s\S]*?\n[ \t]*\};\n[ \t]*<\/script>\n?/;
  if (!re.test(src)) { console.log(`${file}: no config block found`); continue; }
  fs.writeFileSync(p, src.replace(re, ""));
  console.log(`${file}: config block removed`);
}

// 2. Add the @theme tokens once to the stylesheet
const cssPath = `${root}/css/style.css`;
const css = fs.readFileSync(cssPath, "utf8");
if (!css.includes("@theme")) {
