  --color-cyan: #4CC9F0;
  --color-success: #32D583;
  --color-warning: #FDB022;
  --color-danger: #F97066;
  --color-danger-bright: #FDA29B;
  --color-easy: #32D583;
  --color-medium: #FDB022;
