  // collect from the opening <script> (line 1-indexed startLine) to first </script>
  let openIdx = -1;
  for (let i = startLine - 1; i < lines.length; i++) {
    if (/<script(?:\s|>)/.test(lines[i]) && !/src=/.test(lines[i])) { openIdx = i; break; }
  }
  if (openIdx === -1) { console.log(file, "no inline script found"); bad++; continue; }
  let closeIdx = -1;
  for (let i = openIdx + 1; i < lines.length; i++) {
    if (lines[i].includes("</script>")) { closeIdx = i; break; }
  }
  const code = lines.slice(openIdx + 1, closeIdx).join("\n");
  const out = `/tmp/inline-${file.replace(".html", "")}.js`;
  writeFileSync(out, code);
  try {
    execFileSync("node", ["--check", out], { stdio: "pipe" });
    console.log(file, "inline script syntax: OK");
  } catch (e) {
    console.log(file, "inline script syntax ERROR:\n" + e.stderr.toString());
    bad++;
  }
}
process.exit(bad ? 1 : 0);
